head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[selectbox > P > submenuSize]<br/>아이템 리스트창의 너비(Width)를 결정하는 기준을 설정합니다.",
    "validation" : [            
        "renderType=component 이고, 아이템이 BindItemSet 으로 정의된 경우에 동작합니다.",
        "미설정 시 아이템 리스트창의 너비를 가장 긴 아이템에 맞춥니다.",
        "fixed 설정 시 아이템 리스트창의 너비를 SelectBox 컴포넌트의 너비에 맞춥니다.",
        "auto 설정 시 아이템 리스트창의 너비를 가장 긴 아이템에 맞춥니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {        
        submenuSize : con_submenuSize.getText(),
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    // comp 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<xf:select1 ' + strNameSpace + ' ' + cList + ' ' + eList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_selectboxItem">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:select1>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "selectbox",
        strTarget,
        grp_comp
    );
}



scwin.btn_getItemListSize_onclick = function (e) {
    let rtn = '';    
    let comp = "target1_itemTable";
    let targetElements = document.querySelectorAll('[id*='+comp+']');

    if (targetElements.length == 0)
            wf_body_bottom.getObj("scwin").setReturnValue("SelectBox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    rtn = targetElements[0].style.width
    wf_body_bottom.getObj("scwin").setReturnValue("Itemlist width : " + rtn);
};



scwin.target1_onclick = function (e) {
    scwin.btn_getItemListSize_onclick();
}
